Ltac fs_step :=
  first [ progress (rewrite ?fs_reg_get_set; fs_eqb_simp)
        | match goal with H : fs_agree ?F1 ?F2 |- context [reg_get ?F2 ?r] => rewrite (fs_agree_get F1 F2 r H) by reflexivity end
        | match goal with H : fs_agree_but ?ex ?F1 ?F2 |- context [reg_get ?F2 ?r] => rewrite (H r eq_refl eq_refl) end ].

(* [comment removed for export] *)
Ltac fs_close :=
  let r := fresh "r" in let Hr := fresh "Hr" in let Hx := fresh "Hx" in
  lazymatch goal with
  | |- fs_agree _ _ => intros r Hr
  | |- fs_agree_but _ _ _ => intros r Hr Hx
  end;
  apply fs_callee_cases in Hr; cbn [map In] in Hr;
  repeat (destruct Hr as [<-|Hr]); [..| destruct Hr];
  try (exfalso; vm_compute in Hx; discriminate Hx);
  repeat fs_step; reflexivity.

